function smsTypeLabel(type) { return { confirmation: "Подтверждение записи", reminder_day: "Напоминание за день", reminder_2h: "Напоминание за 2 часа", reschedule: "Перенос записи", review: "Благодарность + отзыв" }[type] || type; }
